// Microphone chord recognition, tested with synthetic guitar strums fed to Chromium as a fake microphone.
// The WAV files are generated by tests/fixtures/make-strums.py (run it once if they are missing).
const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('path');
const fs = require('fs');
const { execFileSync } = require('child_process');
const { chromium } = require('playwright');
const serve = require('./serve');
const FIX = path.join(__dirname, '..', 'fixtures');
if (!fs.existsSync(path.join(FIX, 'strum-G.wav'))) execFileSync('python3', [path.join(FIX, 'make-strums.py'), FIX]);

async function heard(file, expect, ms) {
  const srv = serve(path.join(__dirname, '..', '..', 'app'), 8791);
  const b = await chromium.launch({ args: ['--use-fake-ui-for-media-stream', '--use-fake-device-for-media-stream', '--use-file-for-fake-audio-capture=' + path.join(FIX, file)] });
  try {
    const p = await (await b.newContext({ permissions: ['microphone'] })).newPage();
    await p.goto('http://localhost:8791/');
    return await p.evaluate(async ([expect, ms]) => {
      const got = [];
      await MicChords.start(chordWatcher(() => expect, n => got.push(n)));
      await new Promise(r => setTimeout(r, ms));
      MicChords.stop();
      return got;
    }, [expect, ms]);
  } finally { await b.close(); srv.close(); }
}

test('hears a G chord when G is strummed', async () => {
  const got = await heard('strum-G.wav', ['G'], 6000);
  assert.ok(got.length >= 1, 'G was recognised');
});
test('does not accept G when E minor is strummed', async () => {
  const got = await heard('strum-Em.wav', ['G'], 6000);
  assert.equal(got.length, 0);
});
test('hears C, not G, when it expects C during a G – C change', async () => {
  const got = await heard('strum-G-C.wav', ['C'], 8000);
  assert.ok(got.length >= 1, 'C was recognised');
});

test('song lab: a guide track is recorded in sync with the song and mixed into the audio export', async () => {
  const srv = serve(path.join(__dirname, '..', '..', 'app'), 8792);
  const b = await chromium.launch({ args: ['--use-fake-ui-for-media-stream', '--use-fake-device-for-media-stream', '--use-file-for-fake-audio-capture=' + path.join(FIX, 'strum-G.wav'), '--autoplay-policy=no-user-gesture-required'] });
  try {
    const ctx = await b.newContext({ permissions: ['microphone'], acceptDownloads: true });
    const p = await ctx.newPage(); const errors = []; p.on('pageerror', e => errors.push(e.message));
    await p.goto('http://localhost:8792/');
    await p.evaluate(() => { const g = window.__gpa; g.S().profile.onboarded = true; g.go('song'); g.ACTIONS.slnew(); const P = g.S().songs[0]; P.bpm = 120; P.structure = ['Chorus']; g.go('song', { pid: P.id }); });
    await p.click('#guiderec');
    await p.waitForFunction(() => window.__gpa.S().songs[0].guide, null, { timeout: 30000 });
    const dur = await p.evaluate(() => window.__gpa.S().songs[0].guide.dur);
    const peak = await p.evaluate(async () => { const P = window.__gpa.S().songs[0]; const b = await GuideStore.buffer(P); return guidePeak(b.getChannelData(0)); });
    assert.ok(peak > 0.8 && peak <= 0.95, 'the take is brought to a healthy level, got ' + peak);
    assert.ok(dur >= 7 && dur <= 10, 'about 8 seconds recorded, got ' + dur);
    // the song with its recorded track, mixed and mastered (24-bit WAV with the song details)
    await p.waitForSelector('[data-act=pexp][data-format=wav]');
    const [dl] = await Promise.all([p.waitForEvent('download', { timeout: 120000 }), p.click('[data-act=pexp][data-format=wav]')]);
    const buf = fs.readFileSync(await dl.path());
    assert.equal(buf.toString('latin1', 8, 12), 'WAVE'); assert.equal(buf.readUInt16LE(34), 24);
    assert.match(dl.suggestedFilename(), /_master_/);
    assert.ok(buf.includes(Buffer.from('INFO')) && buf.includes(Buffer.from('Gospel Music Academy')), 'song details in the file');
    await p.waitForFunction(() => /LUFS/.test(document.querySelector('#expinfo').textContent), null, { timeout: 60000 });
    assert.deepEqual(errors, []);
  } finally { await b.close(); srv.close(); }
});

test('song lab: a silent microphone saves nothing and explains how to fix it', async () => {
  const silent = path.join(FIX, 'silence.wav');
  if (!fs.existsSync(silent)) execFileSync('python3', ['-c', 'import wave,sys;w=wave.open(sys.argv[1],"wb");w.setnchannels(1);w.setsampwidth(2);w.setframerate(48000);w.writeframes(bytes(48000*12*2));w.close()', silent]);
  const srv = serve(path.join(__dirname, '..', '..', 'app'), 8793);
  const b = await chromium.launch({ args: ['--use-fake-ui-for-media-stream', '--use-fake-device-for-media-stream', '--use-file-for-fake-audio-capture=' + silent, '--autoplay-policy=no-user-gesture-required'] });
  try {
    const p = await (await b.newContext({ permissions: ['microphone'] })).newPage(); const errors = []; p.on('pageerror', e => errors.push(e.message));
    await p.goto('http://localhost:8793/');
    await p.evaluate(() => { const g = window.__gpa; g.S().profile.onboarded = true; g.go('song'); g.ACTIONS.slnew(); const P = g.S().songs[0]; P.bpm = 160; P.structure = ['Chorus']; g.go('song', { pid: P.id }); });
    assert.ok(await p.$('#guidemic') && await p.$('#guidetest'), 'microphone picker and test are shown');
    await p.click('#guiderec');
    await p.waitForFunction(() => /did not pick up any sound/.test(document.querySelector('#guideinfo').textContent), null, { timeout: 30000 });
    assert.equal(await p.evaluate(() => window.__gpa.S().songs[0].guide || null), null);
    assert.deepEqual(errors, []);
  } finally { await b.close(); srv.close(); }
});
